var a=`0271-kranjska-klobasa`;var n=`world-0271`;var s=`SI`;var i=`southern-europe`;var r=4;var o=18;var g={en:`Kranjska Klobasa`,ua:`Кранська ковбаса`};var d={en:`A Slovenian-style cooked sausage serving made with catalog bratwurst; authentic Kranjska klobasa is not present in the catalog.`,ua:`Подача ковбаси по-словенськи з братвурстом; автентичної кранської ковбаси в каталозі немає.`};var l=[{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 16 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 16 хвилин до м’якості та готовності.`,t:[`simmering`],m:16,i:[[`bratwurst`,700,`g`],[`water`,750,`ml`],[`bay-leaf`,1,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`dijon-mustard`,80,`g`],[`horseradish-root`,45,`g`]]}];var u={slug:a,id:n,country:`SI`,region:i,servings:4,minutes:18,title:g,text:d,steps:l};export{s as country,u as default,n as id,o as minutes,i as region,r as servings,a as slug,l as steps,d as text,g as title};